import{_ as n,o as a,c as i,a6 as l}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"应急响应","description":"出事时最贵的是犹豫——一份可以照着执行的六阶段流程、「先取证还是先断网」这个经典两难怎么判、以及个人站也能提前十分钟准备好的应急包。","frontmatter":{"title":"应急响应","description":"出事时最贵的是犹豫——一份可以照着执行的六阶段流程、「先取证还是先断网」这个经典两难怎么判、以及个人站也能提前十分钟准备好的应急包。","source":"https://daiw.org/manual/web-security/incident-response"},"headers":[],"relativePath":"manual/computer-programming/web-security/incident-response.md","filePath":"manual/computer-programming/web-security/incident-response.md"}'),t={name:"manual/computer-programming/web-security/incident-response.md"};function e(p,s,r,o,h,d){return a(),i("div",null,[...s[0]||(s[0]=[l(`<h1 id="应急响应" tabindex="-1">应急响应 <a class="header-anchor" href="#应急响应" aria-label="Permalink to &quot;应急响应&quot;">​</a></h1><p>出事时最贵的是犹豫——一份可以照着执行的六阶段流程、「先取证还是先断网」这个经典两难怎么判、以及个人站也能提前十分钟准备好的应急包。</p><p>安全事件的处置质量，<strong>几乎完全取决于事前准备</strong>。事发当下人是慌的、判断是差的、时间是不够的——<strong>你能依靠的只有提前写好的东西</strong>。</p><p>这一章给一份可以照着执行的流程。</p><h2 id="六个阶段" tabindex="-1">六个阶段 <a class="header-anchor" href="#六个阶段" aria-label="Permalink to &quot;六个阶段&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 准备 → ② 发现与确认 → ③ 遏制 → ④ 根除 → ⑤ 恢复 → ⑥ 复盘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>① 准备</strong>是唯一可以从容做的阶段，也是决定其余五个阶段能否顺利的关键。</p><h2 id="_1-准备-现在就做" tabindex="-1">① 准备（现在就做） <a class="header-anchor" href="#_1-准备-现在就做" aria-label="Permalink to &quot;① 准备（现在就做）&quot;">​</a></h2><h3 id="一份写下来的应急信息卡" tabindex="-1">一份写下来的应急信息卡 <a class="header-anchor" href="#一份写下来的应急信息卡" aria-label="Permalink to &quot;一份写下来的应急信息卡&quot;">​</a></h3><p>放在<strong>不依赖你自己系统</strong>的地方（因为出事时你的系统可能正好用不了）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【联系人】</span></span>
<span class="line"><span>  谁能决定「下线服务」            —— 姓名、电话</span></span>
<span class="line"><span>  谁有域名注册商账号             —— 姓名、电话</span></span>
<span class="line"><span>  谁有云账号的最高权限           —— 姓名、电话</span></span>
<span class="line"><span>  云厂商工单入口 / 客服电话</span></span>
<span class="line"><span>  法务或合规联系人（涉及用户数据时）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【系统清单】</span></span>
<span class="line"><span>  域名与注册商、DNS 托管方</span></span>
<span class="line"><span>  服务器 IP / 云资源清单</span></span>
<span class="line"><span>  数据库位置、备份位置与恢复方式</span></span>
<span class="line"><span>  第三方服务清单（支付、短信、OAuth）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【应急凭据】</span></span>
<span class="line"><span>  离线保存的一份紧急访问方式（硬件密钥备份 / 打印的恢复码）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>最容易出问题的是「只有一个人有关键账号」。</strong> 那个人休假、手机丢了、或者恰好就是被社工的对象——整个响应就卡住了。</p><p>至少要有<strong>两个人</strong>能访问域名注册商和云账号，且恢复码离线备份（打印出来放保险柜，不是存在那台可能被加密的电脑里）。</p></div><h3 id="提前想清楚一个问题" tabindex="-1">提前想清楚一个问题 <a class="header-anchor" href="#提前想清楚一个问题" aria-label="Permalink to &quot;提前想清楚一个问题&quot;">​</a></h3><p><strong>「什么情况下我们会主动下线服务？」</strong></p><p>事发当下讨论这个问题，会因为「怕影响业务」而拖延。<strong>提前定好触发条件</strong>：</p><ul><li>确认数据正在被批量外传 → 立即断</li><li>确认服务器被植入后门 → 立即隔离</li><li>疑似但未确认 → 先加强监控，不下线</li></ul><h2 id="_2-发现与确认" tabindex="-1">② 发现与确认 <a class="header-anchor" href="#_2-发现与确认" aria-label="Permalink to &quot;② 发现与确认&quot;">​</a></h2><p>收到告警或外部报告后，<strong>第一件事是确认真实性</strong>，不要立刻拔网线（除非命中上面的触发条件）。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 快速体检</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">who</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # 有谁登录着</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">last</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # 最近登录记录</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auxf</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                               # 异常进程（尤其是父进程为 1 的）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tulpn</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                             # 异常监听端口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crontab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/cron.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 计划任务后门</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -newermt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-24 hours&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 24 小时内变更的 Web 文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>记录你做的每一步和时间</strong>。这不只是给事后复盘用——如果涉及法律程序，操作记录本身就是证据链的一部分。</p><h2 id="_3-遏制-先止血" tabindex="-1">③ 遏制：先止血 <a class="header-anchor" href="#_3-遏制-先止血" aria-label="Permalink to &quot;③ 遏制：先止血&quot;">​</a></h2><p>这个阶段的目标是<strong>阻止损失扩大</strong>，不是查清原因。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>经典两难：先取证还是先断网？</strong></p><ul><li><strong>先断网</strong> → 止损快，但内存里的证据（正在运行的恶意进程、网络连接、解密后的载荷）会丢失。</li><li><strong>先取证</strong> → 证据全，但攻击者还在里面继续搞。</li></ul><p><strong>给绝大多数场景的建议：先隔离，不要关机。</strong></p><p>「隔离」是把机器从网络里摘出来（改安全组、断网卡），<strong>但保持运行</strong>。这样既切断了攻击者的通路和数据外带，又保住了内存中的证据。</p><p><strong>关机是最糟的选择</strong>——它同时丢失内存证据，而且不比隔离更安全。</p></div><p>按情况选择遏制手段：</p><table tabindex="0"><thead><tr><th>情况</th><th>动作</th></tr></thead><tbody><tr><td>单台服务器被控</td><td>从负载均衡摘掉 + 网络隔离，<strong>保持运行</strong></td></tr><tr><td>凭据泄露</td><td><strong>立即轮换</strong>（<a href="/Front2Full/manual/computer-programming/web-security/secrets">密钥那章</a>讲过，这是唯一止血动作）</td></tr><tr><td>某个账号被盗</td><td>强制登出该用户所有会话 + 冻结账号</td></tr><tr><td>正在被拖数据</td><td>收紧数据库权限 / 断开应用与数据库</td></tr><tr><td>域名被劫持</td><td>联系注册商，走紧急申诉通道</td></tr><tr><td>大面积沦陷</td><td>触发预案，整体下线并挂公告页</td></tr></tbody></table><p><strong>同时保存证据</strong>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 内存镜像（如果有条件，在隔离后立刻做）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 磁盘镜像</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if=/dev/sda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of=/mnt/evidence/disk.img</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bs=4M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status=progress</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 至少把日志复制出来（复制到别的机器，不要留在可能被清的机器上）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> czf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/evidence/logs-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/logs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="_4-根除" tabindex="-1">④ 根除 <a class="header-anchor" href="#_4-根除" aria-label="Permalink to &quot;④ 根除&quot;">​</a></h2><p><strong>这一阶段最重要的原则</strong>：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>被完全控制过的服务器，不要「清理干净后继续用」——重装。</strong></p><p>理由很实在：你无法证明自己找全了所有后门。攻击者可能改了系统二进制、加了内核模块、在计划任务/systemd unit/<code>.bashrc</code>/SSH authorized_keys 里留了多处持久化。<strong>漏掉一处，几周后他就回来了</strong>——而且这次他知道你在看什么。</p><p>容器化的一个巨大好处正在这里：<strong>重建一个容器是几分钟的事</strong>，从可信的镜像重新拉起，干净利落。这也是为什么「不可变基础设施」是安全实践而不只是运维实践。</p></div><p>根除清单：</p><ul><li>[ ] 找到并修复<strong>入口漏洞</strong>（没修这个，重装也白搭）</li><li>[ ] 从可信来源重装/重建系统</li><li>[ ] <strong>轮换所有可能接触过的凭据</strong>——数据库密码、API key、SSH 密钥、云凭据、会话密钥</li><li>[ ] 检查并清理持久化点：cron、systemd、<code>authorized_keys</code>、启动脚本、容器镜像</li><li>[ ] 强制所有用户重新登录（使全部会话失效）</li><li>[ ] 如果密码哈希可能泄露，<strong>强制用户改密码</strong></li></ul><h2 id="_5-恢复" tabindex="-1">⑤ 恢复 <a class="header-anchor" href="#_5-恢复" aria-label="Permalink to &quot;⑤ 恢复&quot;">​</a></h2><p>分阶段恢复，<strong>不要一次性全放开</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 在隔离环境重建 → 验证功能与安全配置</span></span>
<span class="line"><span>2. 小流量灰度 → 密切监控</span></span>
<span class="line"><span>3. 逐步放开</span></span>
<span class="line"><span>4. 保持高强度监控至少 2 周</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>为什么要监控两周</strong>：攻击者常常会回来试探。<strong>这段时间的告警阈值应该调低</strong>，宁可多几次误报。</p><p><strong>恢复数据时的关键判断</strong>：</p><ul><li>备份是在入侵<strong>之前</strong>还是<strong>之后</strong>做的？</li><li>如果不确定入侵时间点，往前多回溯几个版本</li><li><strong>备份里可能已经包含了后门</strong>——恢复后要重新检查</li></ul><h2 id="_6-复盘" tabindex="-1">⑥ 复盘 <a class="header-anchor" href="#_6-复盘" aria-label="Permalink to &quot;⑥ 复盘&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>复盘必须是「对事不对人」的（blameless）。</strong></p><p>如果复盘会变成追责会，下一次有人发现异常时<strong>会倾向于隐瞒或自己偷偷处理</strong>——而这会让下一次事故严重十倍。</p><p><strong>要回答的问题</strong>：</p><ol><li><strong>怎么进来的？</strong> 具体到哪个漏洞、哪个配置、哪个流程缺口。</li><li><strong>为什么没早点发现？</strong> 缺哪条监控？告警响了但被忽略了吗？</li><li><strong>影响范围到底多大？</strong> 基于日志给出结论，不要靠猜。</li><li><strong>哪些措施本可以阻止或减轻？</strong> 对应到具体的待办。</li><li><strong>同类问题在别处还有吗？</strong> ——<strong>这一条最容易漏，也最有价值。</strong> 一个越权漏洞往往不止一处。</li></ol></div><p>产出必须是<strong>带负责人和截止日期的行动项</strong>，不是一份感想。</p><h2 id="涉及用户数据时" tabindex="-1">涉及用户数据时 <a class="header-anchor" href="#涉及用户数据时" aria-label="Permalink to &quot;涉及用户数据时&quot;">​</a></h2><p>这不再只是技术问题：</p><ul><li><strong>法律义务</strong>：中国有《个人信息保护法》《数据安全法》《网络安全法》，欧盟有 GDPR（72 小时内报告），各地要求不同——<strong>提前搞清楚适用于你的规则</strong>。</li><li><strong>通知用户</strong>：说清楚泄露了什么、可能的影响、用户该做什么（改密码、留意可疑信息）。</li><li><strong>诚实</strong>：<strong>隐瞒或淡化造成的二次伤害，通常远大于事件本身。</strong> 用户能原谅一次事故，很难原谅一次欺骗。</li></ul><h2 id="一个人的最小预案" tabindex="-1">一个人的最小预案 <a class="header-anchor" href="#一个人的最小预案" aria-label="Permalink to &quot;一个人的最小预案&quot;">​</a></h2><p>如果你就是一个人维护一个个人站，把这些准备好就够了：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 域名注册商与云账号的恢复码 —— 打印出来，离线保存</span></span>
<span class="line"><span>2. 一份写下来的系统清单（域名、服务器、数据库、第三方服务）</span></span>
<span class="line"><span>3. 备份能恢复 —— 而且亲手演练过一次</span></span>
<span class="line"><span>4. 知道怎么快速下线：</span></span>
<span class="line"><span>   - 把 DNS 指向一个静态公告页，或</span></span>
<span class="line"><span>   - 在 CDN 上开「维护模式」</span></span>
<span class="line"><span>5. 服务器重建脚本 / Docker Compose 文件在 git 里 —— 能快速在新机器上拉起</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>第 3 条的「亲手演练过一次」是重点</strong>。没恢复过的备份，只是一堆你以为能用的文件——真到用的时候才发现格式不对、缺文件、或者密码忘了，这种事非常常见。</p><p><strong>第 5 条也很实在</strong>：本站（daiw）的两条产线都是 Docker + git 里的 compose 文件，理论上换一台机器几分钟就能重建。<strong>这种可重建性本身就是安全能力</strong>——它让「重装而不是清理」变成一个容易做的选择。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>处置质量取决于事前准备</strong>，事发当下人是慌的。</li><li>应急信息卡要放在<strong>不依赖自己系统</strong>的地方；关键账号<strong>至少两个人</strong>能访问。</li><li>遏制阶段：<strong>先隔离，不要关机</strong>——保住内存证据，同时切断通路。</li><li><strong>被完全控制过的服务器要重装，不要清理后继续用</strong>；容器化让这件事变得廉价。</li><li>根除必须先<strong>修入口漏洞</strong>，并<strong>轮换所有可能接触过的凭据</strong>。</li><li>恢复后<strong>高强度监控两周</strong>，攻击者常会回来试探。</li><li><strong>复盘必须 blameless</strong>，否则下次事故会被隐瞒；最有价值的一问是「同类问题在别处还有吗」。</li><li>一个人的最小预案：<strong>恢复码离线、系统清单、演练过的备份、快速下线手段、可重建的部署配置</strong>。</li></ul><p>专栏正文到此结束。最后给一份可以逐条打勾的清单。👉 <a href="/Front2Full/manual/computer-programming/web-security/checklist">上线安全检查清单</a></p>`,52)])])}const k=n(t,[["render",e]]);export{g as __pageData,k as default};
